    {
      "category": "embedding_representation",
      "rationale": "Normalize the shared item embeddings on every history and target lookup, keeping padding exactly zero. This tests whether embedding direction improves discrimination without item magnitude. Width, GRU topology, dot-product scoring, loss and optimizer stay fixed. Checkpoint shapes remain unchanged; the generated predictor dynamically imports the updated model class.",
      "edits": [
        {
          "find": "class GRU4RecModel(nn.Module):",
          "replace": "class UnitNormItemEmbedding(nn.Embedding):\n    def forward(self, indices: torch.Tensor) -> torch.Tensor:\n        embeddings = super().forward(indices)\n        embeddings = torch.nn.functional.normalize(embeddings, p=2, dim=-1, eps=1e-12)\n        return embeddings.masked_fill(indices.eq(0).unsqueeze(-1), 0.0)\n\n\nclass GRU4RecModel(nn.Module):"
        },
        {
          "find": "        self.item_emb = nn.Embedding(itemnum + 1, hidden_units, padding_idx=0)",
          "replace": "        self.item_emb = UnitNormItemEmbedding(itemnum + 1, hidden_units, padding_idx=0)"
        }
      ]
    }
  ],
  "change_summary": "Apply unit L2 normalization to all shared item embedding lookups across all four category models, preserving zero padding and predictor/checkpoint compatibility."
}
